isolation="<script>(()=>{const d=new Map(),s={getItem:k=>d.get(k)??null,setItem:(k,v)=>d.set(k,String(v)),removeItem:k=>d.delete(k),clear:()=>d.clear(),key:i=>[...d.keys()][i]??null,get length(){return d.size}};Object.defineProperty(window,'localStorage',{value:s});Object.defineProperty(window,'sessionStorage',{value:s});})();</script>"
payload='<section style="position:fixed;right:8px;bottom:220px;z-index:200001;background:#162636;color:white;padding:8px;font:11px system-ui;max-width:260px"><button id="reelActualQA">Open real chest</button><button id="reelSkipQA">Skip</button><button id="reelReduceQA">Reduced motion chest</button><button id="reelClearQA">Clear queue</button><button id="reelReportQA">Report</button><pre id="reelResultQA">Loading</pre></section><script>\n(async()=>{const wait=()=>new Promise(r=>setTimeout(r,50));while(!window.__BF3||!window.HERO3D?.ready)await wait();const b=__BF3;await b.briarReady;b.loadMode(\'rl\');Object.assign(b.meta,LEGACY);b.meta.run=null;b.meta.originSeen=true;b.meta.introSeen=true;b.meta.hubTutDone=true;b.meta.autoAttack=false;b.meta.autoSellEquipment=false;b.openHub();while(BF_LOADING.active)await wait();let chestSerial=0,ticks=0,reveals=0,expected=null,lastChest=null,baseBag=b.meta.stash.length;const oldTick=b.SFX.lootTick,oldReveal=b.SFX.achieve;b.SFX.lootTick=function(){ticks++;return oldTick.call(this);};b.SFX.achieve=function(){reveals++;return oldReveal.call(this);};\nfunction open(reduce=false){b.meta.reduceMotion=reduce;lastChest={x:90+(++chestSerial)*20,y:0,z:80,rarity:\'rare\',opened:false};baseBag=b.meta.stash.length;b.openChest(lastChest);expected=b.meta.stash.at(-1);b.openChest(lastChest);report();}\nfunction report(){document.getElementById(\'reelResultQA\').textContent=JSON.stringify({ticks,reveals,active:BFChestReveal.active,settled:!!document.querySelector(\'#chest-reveal.settled\'),name:document.querySelector(\'#chest-reveal .cr-title\')?.textContent,bagDelta:b.meta.stash.length-baseBag,item:expected&&(expected.weapon||expected.armor||expected.trinket)?.name,gold:b.meta.gold,level:b.G.p.level,muted:b.meta.soundOn===false},null,2);}\ndocument.getElementById(\'reelActualQA\').onclick=()=>open();document.getElementById(\'reelReduceQA\').onclick=()=>open(true);document.getElementById(\'reelSkipQA\').onclick=()=>{BFChestReveal.skip();report();};document.getElementById(\'reelClearQA\').onclick=()=>{BFChestReveal.clear();report();};document.getElementById(\'reelReportQA\').onclick=report;document.getElementById(\'reelResultQA\').textContent=\'Ready\';})();</script>'
